"""Render reviewed charts: common-unit counts and visible kappa, without relabelling."""
from pathlib import Path
import csv,json,copy
import vl_convert as vlc
R=Path(__file__).resolve().parents[1];C=R/'charts';C.mkdir(exist_ok=True)
base={'$schema':'https://vega.github.io/schema/vega-lite/v5.json','width':560,'height':240,'background':'#fbfaf7','config':{'font':'Arial','axis':{'labelFontSize':12,'titleFontSize':13},'title':{'fontSize':16,'subtitleFontSize':12},'view':{'stroke':None}}}
s1=copy.deepcopy(base);s1.update({'title':{'text':'Cognitive use: two passes of the same model','subtitle':['The same 51 metaphor-marked word units in both passes','Pass A had manuscript/codebook context; Pass B started fresh']},'data':{'url':'charts/1-cognitive-use.csv'},'params':[{'name':'pass_select','select':{'type':'point','fields':['pass_id']},'bind':'legend'}],'mark':'bar','encoding':{'x':{'field':'category','type':'nominal','title':'Assigned cognitive use','sort':['attributive','constitutive','mixed','uncertain'],'axis':{'labelAngle':0}},'xOffset':{'field':'pass_id','type':'nominal'},'y':{'field':'units','type':'quantitative','title':'Units among the common 51','axis':{'tickMinStep':1}},'color':{'field':'pass_id','type':'nominal','title':'Pass','scale':{'domain':['A','B'],'range':['#176a8a','#c36b20']}},'opacity':{'condition':{'param':'pass_select','value':1},'value':0.25},'tooltip':[{'field':'pass_id','title':'Pass'},{'field':'category','title':'Cognitive use'},{'field':'units','type':'quantitative','title':'Units'},{'field':'n','type':'quantitative','title':'Common metaphor units'},{'field':'documents','type':'quantitative','title':'Passages'}]}})
s2=copy.deepcopy(base);s2['height']=280
order=['Cognitive use','Figurative appeal','Social label sets','Textual binding','Scope in excerpt']
s2.update({'title':{'text':'Raw agreement can hide poor replication','subtitle':['n = 51 common metaphor-marked word units','Labels show raw agreement and Cohen’s κ; bars show raw agreement']},'data':{'url':'charts/2-agreement.csv'},'encoding':{'y':{'field':'display','type':'nominal','sort':order,'title':None},'tooltip':[{'field':'display','title':'Dimension'},{'field':'n','type':'quantitative','title':'Paired units'},{'field':'agree','type':'quantitative','title':'Agree'},{'field':'disagree','type':'quantitative','title':'Disagree'},{'field':'agreement_percent','type':'quantitative','title':'Raw agreement (%)'},{'field':'kappa','title':'Cohen’s kappa'}]},'layer':[{'mark':{'type':'bar','color':'#26755b'},'encoding':{'x':{'field':'agreement_percent','type':'quantitative','scale':{'domain':[0,100]},'title':'Exact agreement (%)'}}},{'mark':{'type':'text','align':'left','baseline':'middle','fontSize':12,'fontWeight':'bold','color':'white'},'encoding':{'x':{'value':8},'text':{'field':'label','type':'nominal'}}}]})
for name,spec in [('1-cognitive-use',s1),('2-agreement',s2)]:
 rows=list(csv.DictReader((C/f'{name}.csv').open()));assert rows
 (C/f'{name}.vl.json').write_text(json.dumps(spec,ensure_ascii=False,indent=2)+'\n')
 render=copy.deepcopy(spec);render['data']={'values':rows};(C/f'{name}.png').write_bytes(vlc.vegalite_to_png(render,scale=2))
 print(name,'rendered',len(rows),'exact plotted rows')
